def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    div_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    rb = [-1] + div_rows + [h]
    cb = [-1] + div_cols + [w]
    rows = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    cols = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]

    out = [row[:] for row in grid]
    tiles = []
    for r0, r1 in rows:
        for c0, c1 in cols:
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] != background]
            if cells:
                tiles.append((r1 - r0, c1 - c0, cells))

    if not tiles:
        return out

    # Use the most populated panel as the motif and repeat it in matching panels.
    th, tw, motif = max(tiles, key=lambda t: len(t[2]))
    for r0, r1 in rows:
        for c0, c1 in cols:
            if r1 - r0 != th or c1 - c0 != tw:
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = background
            for dr, dc, color in motif:
                out[r0 + dr][c0 + dc] = color
    return out
